-- Purpose: dims.json source (plants, material groups, material types, criticality, movement classes, inventory statuses) + KPI DISCLAIMER + data date (MAX AS_OF_DATE).
-- Result rows: 37
-- Data asset id: 6b06eceb5be48659f48aca62 (sync 49656a19-3175-4010-a414-2dc8971dd234, r1-dims-20261125-1413). Content read back: ASOF = 2025-12-31.
-- Note: ALL_PLANTS excluded from DIM_PLANT.
SELECT 'PLANT' AS K, PLANT_ID AS CODE, PLANT_NAME AS NAME, PLANT_TYPE AS EXTRA, REGION_LABEL AS EXTRA2 FROM VEDANTA_POC.DIM_PLANT WHERE PLANT_ID <> 'ALL_PLANTS' UNION ALL SELECT 'GROUP', MATERIAL_GROUP, MATERIAL_GROUP, BASE_UOM, '' FROM VEDANTA_POC.REF_MATERIAL_GROUP UNION ALL SELECT DISTINCT 'TYPE', MATERIAL_TYPE, MATERIAL_TYPE, '', '' FROM VEDANTA_POC.DIM_MATERIAL WHERE MATERIAL_TYPE IN ('ZSPR','ZSPN') UNION ALL SELECT 'CRITICALITY', CRITICALITY, CRITICALITY, TO_VARCHAR(SERVICE_LEVEL_PCT), '' FROM VEDANTA_POC.REF_CRITICALITY UNION ALL SELECT DISTINCT 'MOVEMENT_CLASS', MOVEMENT_CLASS, MOVEMENT_CLASS, '', '' FROM VEDANTA_POC.INVENTORY_CLASSIFICATION UNION ALL SELECT DISTINCT 'INVENTORY_STATUS', INVENTORY_STATUS, INVENTORY_STATUS, '', '' FROM VEDANTA_POC.INVENTORY_CLASSIFICATION UNION ALL SELECT DISTINCT 'DISCLAIMER', 'DISCLAIMER', DISCLAIMER, '', '' FROM VEDANTA_POC.INVENTORY_KPI_MONTHLY UNION ALL SELECT 'ASOF', 'ASOF', TO_VARCHAR(MAX(AS_OF_DATE),'YYYY-MM-DD'), '', '' FROM VEDANTA_POC.INVENTORY_CLASSIFICATION ORDER BY 1, 2
